package db

import (
	_ "embed"
	"encoding/json"
	"log/slog"
)

// pop_gated.json is the precomputed result of buildPoPGated — a sorted list of
// PoP-gated item IDs — regenerated by cmd/pop-index whenever quarm.db changes
// (like quest_sources.json and the AA descriptions). Computing the set live is
// a multi-second pass over the loot/spawn join tables, so we do it once at
// build time and just load the answer at runtime.
//
//go:embed pop_gated.json
var popGatedJSON []byte

// popExpansion is the zoneCatalog bucket id for Planes of Power. Items whose
// only sources live in PoP zones are not yet obtainable on Project Quarm.
const popExpansion = 4

// IsPoPGated reports whether an item is Planes-of-Power-gated — i.e. not
// obtainable in the current (pre-PoP) era — so the upgrade finder can hide it
// by default via its own show_pop filter. Safe default: an item we can't
// classify is treated as available (false).
func (db *DB) IsPoPGated(itemID int) bool {
	db.ensurePoPIndex()
	return db.popGated[itemID]
}

// ensurePoPIndex loads the PoP item set once. It prefers the precomputed
// pop_gated.json embedded at build time (instant); if that's missing or empty
// — e.g. it wasn't regenerated after a quarm.db update — it falls back to
// building the set live from the DB so gating still works (just slowly) rather
// than silently hiding nothing. On a hard failure it installs an empty set.
func (db *DB) ensurePoPIndex() {
	db.popOnce.Do(func() {
		if set := loadEmbeddedPoPGated(); len(set) > 0 {
			db.popGated = set
			return
		}
		slog.Warn("db: pop_gated.json missing/empty; building PoP index live (slow) — regenerate with cmd/pop-index")
		gated, err := db.buildPoPGated()
		if err != nil {
			slog.Warn("db: failed to build PoP item index; PoP gear will not be hidden", "err", err)
			db.popGated = map[int]bool{}
			return
		}
		db.popGated = gated
	})
}

// loadEmbeddedPoPGated parses the embedded precomputed set. Returns nil on any
// problem (missing/placeholder/corrupt) so the caller falls back to a live build.
func loadEmbeddedPoPGated() map[int]bool {
	var ids []int
	if err := json.Unmarshal(popGatedJSON, &ids); err != nil || len(ids) == 0 {
		return nil
	}
	set := make(map[int]bool, len(ids))
	for _, id := range ids {
		set[id] = true
	}
	return set
}

// ComputePoPGated builds the PoP-gated item set directly from the database.
// Used only by cmd/pop-index to regenerate the embedded pop_gated.json; the
// running server reads the precomputed set instead (see ensurePoPIndex).
func (db *DB) ComputePoPGated() (map[int]bool, error) { return db.buildPoPGated() }

// buildPoPGated computes the set of items that are PoP-only. The per-item /
// per-zone expansion columns in quarm.db are unreliable, so membership is
// derived from where each item actually comes from:
//
//   - explicitly tagged items (items.min_expansion >= 4), to catch PoP items
//     with no recorded source (e.g. quest rewards), and
//   - items whose every known source zone (drop, vendor, forage, ground spawn,
//     or quest reward) is a PoP zone per the curated zoneCatalog. Drops are
//     read both from where the NPC spawns and — for NPCs with no spawn entry
//     (PoP mobs, which aren't spawned while PoP is locked) — from the NPC's
//     home zone derived from its id, so their drops aren't invisible.
//
// An item with at least one pre-PoP source is kept (it's obtainable now).
//
// Quest rewards are essential here: EQEmu scripts quests in Lua/Perl, not DB
// tables, so a quest-reward item has no drop/vendor/forage row and would
// otherwise be unclassifiable. Folding the quest-source zones in both keeps
// current-era quest gear visible (Sigil Earring of Veracity → Katta/Luclin)
// and correctly hides PoP-era quest rewards (Jade Hoop of Speed → Plane of
// Knowledge). See quest_sources.go.
func (db *DB) buildPoPGated() (map[int]bool, error) {
	gated := map[int]bool{}

	// Explicit tag: trust an item flagged as PoP era even when it has no source.
	if rows, err := db.Query(`SELECT id FROM items WHERE min_expansion >= ?`, popExpansion); err == nil {
		for rows.Next() {
			var id int
			if err := rows.Scan(&id); err != nil {
				rows.Close()
				return nil, err
			}
			gated[id] = true
		}
		// This function also backs the cmd/pop-index generator, so a
		// mid-iteration error must fail loudly rather than bake an incomplete
		// pop_gated.json into a release.
		if err := rows.Err(); err != nil {
			rows.Close()
			return nil, err
		}
		rows.Close()
	} else {
		return nil, err
	}

	// Per-item source-zone classification.
	hasPoP := map[int]bool{}
	hasNonPoP := map[int]bool{}
	classify := func(itemID int, zoneShort string) {
		if zoneCatalog[zoneShort] >= popExpansion {
			hasPoP[itemID] = true
		} else {
			// Zones absent from the catalog are treated as available (non-PoP)
			// so we never over-hide an item with an unknown source.
			hasNonPoP[itemID] = true
		}
	}

	// Each source query yields (item_id, zone_short_name).
	sourceQueries := []string{
		// NPC drops (from where the NPC actually spawns).
		`SELECT lde.item_id, s2.zone
		   FROM loottable_entries lte
		   JOIN lootdrop_entries lde ON lde.lootdrop_id = lte.lootdrop_id
		   JOIN npc_types n ON n.loottable_id = lte.loottable_id
		   JOIN spawnentry se ON se.npcid = n.id
		   JOIN spawngroup sg ON sg.id = se.spawngroupid
		   JOIN spawn2 s2 ON s2.spawngroupID = sg.id
		  WHERE n.loottable_id > 0`,
		// NPC drops from NPCs that have NO spawn entry. PoP NPCs aren't spawned
		// while PoP is locked, so the spawn2 join above misses their drops
		// entirely and the items leak through. Fall back to the NPC's home zone
		// derived from its id: EQEmu numbers zone NPCs as zoneidnumber*1000+n
		// (holds for ~95% of spawned NPCs; only used here where there's no
		// spawn2 truth to contradict it).
		`SELECT lde.item_id, z.short_name
		   FROM loottable_entries lte
		   JOIN lootdrop_entries lde ON lde.lootdrop_id = lte.lootdrop_id
		   JOIN npc_types n ON n.loottable_id = lte.loottable_id
		   JOIN zone z ON z.zoneidnumber = n.id / 1000
		  WHERE n.loottable_id > 0 AND n.id >= 1000
		    AND NOT EXISTS (
		      SELECT 1 FROM spawnentry se
		      JOIN spawngroup sg ON sg.id = se.spawngroupid
		      JOIN spawn2 s2 ON s2.spawngroupID = sg.id
		      WHERE se.npcid = n.id
		    )`,
		// Vendor sales
		`SELECT ml.item, s2.zone
		   FROM merchantlist ml
		   JOIN npc_types n ON n.merchant_id = ml.merchantid
		   JOIN spawnentry se ON se.npcid = n.id
		   JOIN spawngroup sg ON sg.id = se.spawngroupid
		   JOIN spawn2 s2 ON s2.spawngroupID = sg.id
		  WHERE n.merchant_id > 0`,
		// Forage
		`SELECT f.Itemid, z.short_name FROM forage f JOIN zone z ON z.zoneidnumber = f.zoneid`,
		// Ground spawns
		`SELECT g.item, z.short_name FROM ground_spawns g JOIN zone z ON z.zoneidnumber = g.zoneid`,
	}
	for _, q := range sourceQueries {
		rows, err := db.Query(q)
		if err != nil {
			return nil, err
		}
		for rows.Next() {
			var itemID int
			var zone string
			if err := rows.Scan(&itemID, &zone); err != nil {
				rows.Close()
				return nil, err
			}
			if itemID > 0 && zone != "" {
				classify(itemID, zone)
			}
		}
		if err := rows.Err(); err != nil {
			rows.Close()
			return nil, err
		}
		rows.Close()
	}

	// Scripted loot sources (quest Lua, not the DB — see scripted_loot.go).
	// An item a script grants directly is obtainable wherever the granting
	// NPC lives, resolved the same id/1000 way as the spawn2-less fallback
	// above (every entry in scriptedLootByNPC is a PoP-only NPC as of this
	// writing, so this reinforces rather than changes their classification,
	// but it's what actually makes these items resolvable at all now that
	// their DB loot rows are gone — see the 2026-09-27 quarm.db regen).
	for npcID, entries := range scriptedLootByNPC {
		zoneShort, _ := db.scriptedLootZone(npcID)
		if zoneShort == "" {
			continue
		}
		for _, e := range entries {
			classify(e.itemID, zoneShort)
		}
	}

	// Quest-reward sources (from the embedded quest scripts, not the DB). An
	// item rewarded by a quest is obtainable wherever that quest's NPC lives.
	loadQuestSources()
	for itemID, zones := range questRewardZoneSet {
		for zone := range zones {
			classify(itemID, zone)
		}
	}

	// Recipe routes: a combine is another way to get its products, available
	// pre-PoP only when every component is. Without this a quest-combine item
	// (Rosrak's Sleeves of the Primal: PoTime pattern + emblem) had no source
	// row at all and was never gated.
	recipes, err := db.loadPoPRecipes()
	if err != nil {
		return nil, err
	}
	for id := range resolvePoPRoutes(gated, hasPoP, hasNonPoP, recipes) {
		gated[id] = true
	}
	return gated, nil
}

// popRecipe is one enabled tradeskill recipe reduced to what PoP gating needs:
// its consumed components and the items it newly produces.
type popRecipe struct {
	components []int
	products   []int
}

// loadPoPRecipes reads every enabled recipe. Components are entries consumed by
// the combine (componentcount > 0, not the container). Products are successful
// outputs that weren't also inputs, so a tool the combine hands back (recipe
// 9954 returns its Tanaan Smithing Hammer) isn't treated as made by it.
func (db *DB) loadPoPRecipes() ([]popRecipe, error) {
	rows, err := db.Query(`SELECT e.recipe_id, e.item_id, e.successcount,
	    e.componentcount, e.iscontainer
	  FROM tradeskill_recipe_entries e
	  JOIN tradeskill_recipe r ON r.id = e.recipe_id
	  WHERE r.enabled = 1 AND e.item_id > 0`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	type entries struct {
		comps map[int]bool
		outs  []int
	}
	byRecipe := map[int]*entries{}
	order := []int{}
	for rows.Next() {
		var recipeID, itemID, success, comp, container int
		if err := rows.Scan(&recipeID, &itemID, &success, &comp, &container); err != nil {
			return nil, err
		}
		e := byRecipe[recipeID]
		if e == nil {
			e = &entries{comps: map[int]bool{}}
			byRecipe[recipeID] = e
			order = append(order, recipeID)
		}
		if comp > 0 && container == 0 {
			e.comps[itemID] = true
		}
		if success > 0 {
			e.outs = append(e.outs, itemID)
		}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	out := make([]popRecipe, 0, len(order))
	for _, id := range order {
		e := byRecipe[id]
		r := popRecipe{}
		for c := range e.comps {
			r.components = append(r.components, c)
		}
		for _, o := range e.outs {
			if !e.comps[o] {
				r.products = append(r.products, o)
			}
		}
		if len(r.components) > 0 && len(r.products) > 0 {
			out = append(out, r)
		}
	}
	return out, nil
}

// resolvePoPRoutes returns the items that are PoP-only once recipe routes are
// counted alongside the direct sources (hasPoP/hasNonPoP). Each route is PoP,
// available, or unknown:
//
//   - a direct source is PoP or available by its zone;
//   - a recipe is available when every component is available, and PoP when
//     any component is PoP-gated; otherwise (a component with no known source)
//     it's unknown.
//
// An item is gated when it has at least one PoP route and no available one.
// Unknown routes neither gate nor clear an item, so missing data never hides a
// recipe-only item and never un-hides an item that drops only in PoP. tagged
// items (explicit PoP era) are always gated.
//
// Both sets only ever grow, so each is a fixed point; chained combines (a
// combine whose component is itself combined) settle within a few passes.
func resolvePoPRoutes(tagged, hasPoP, hasNonPoP map[int]bool, recipes []popRecipe) map[int]bool {
	avail := map[int]bool{}
	for id := range hasNonPoP {
		if !tagged[id] {
			avail[id] = true
		}
	}
	for changed := true; changed; {
		changed = false
		for _, r := range recipes {
			if !allIn(r.components, avail) {
				continue
			}
			for _, p := range r.products {
				if !avail[p] && !tagged[p] {
					avail[p] = true
					changed = true
				}
			}
		}
	}

	gated := map[int]bool{}
	for id := range tagged {
		gated[id] = true
	}
	for id := range hasPoP {
		if !avail[id] {
			gated[id] = true
		}
	}
	for changed := true; changed; {
		changed = false
		for _, r := range recipes {
			if !anyIn(r.components, gated) {
				continue
			}
			for _, p := range r.products {
				if !avail[p] && !gated[p] {
					gated[p] = true
					changed = true
				}
			}
		}
	}
	return gated
}

func allIn(ids []int, set map[int]bool) bool {
	for _, id := range ids {
		if !set[id] {
			return false
		}
	}
	return true
}

func anyIn(ids []int, set map[int]bool) bool {
	for _, id := range ids {
		if set[id] {
			return true
		}
	}
	return false
}
